import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

/**
 * Claude Code PreToolUse hook: refuse agent Edit/Write on vendored & generated paths.
 *
 * `src/lib/components/ui/` is vendored shadcn-svelte code and `src/lib/data/tracker-data.json` is
 * generated by the pipeline (AGENTS.md §5). The pipeline writes the JSON through Node, not through
 * an agent file tool, so this hook never gets in its way. Exit code 2 blocks the call and feeds
 * stderr back to the agent.
 */

const GUARDED_PATHS = [
  {
    advice:
      "src/lib/components/ui/ is vendored shadcn-svelte code. Update it with the shadcn-svelte CLI in a dedicated PR labeled shadcn-update, or ask the user.",
    pattern: /(^|\/)src\/lib\/components\/ui\//,
  },
  {
    advice:
      "src/lib/data/tracker-data.json is generated. Regenerate it with `pnpm run pipeline -- <assets path>` instead of editing it.",
    pattern: /(^|\/)src\/lib\/data\/tracker-data\.json$/,
  },
];

export interface HookInput {
  cwd?: string;
  tool_input?: { file_path?: unknown; notebook_path?: unknown; path?: unknown };
}

/** Returns the refusal message when the tool call targets a guarded path, else undefined. */
export function guardMessage(input: HookInput): string | undefined {
  const toolInput = input.tool_input ?? {};
  const target = [toolInput.file_path, toolInput.notebook_path, toolInput.path].find(
    (value): value is string => typeof value === "string" && value !== "",
  );
  if (target === undefined) {
    return undefined;
  }
  const absolute = resolve(input.cwd ?? process.cwd(), target).replaceAll("\\", "/");
  const guarded = GUARDED_PATHS.find(({ pattern }) => pattern.test(absolute));
  return guarded === undefined ? undefined : `Blocked edit of ${target}. ${guarded.advice}`;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const message = guardMessage(JSON.parse(readFileSync(0, "utf8")) as HookInput);
  if (message !== undefined) {
    console.error(message);
    process.exitCode = 2;
  }
}
